</blockquote>

<blockquote>
<h4>WRIT OF ERROR.</h4>

<p><i>United States of America, ss.:</i></p>

<p class="ltr-leftF">[<span class="smcap">Seal</span>.]</p>
<p>The President of the United States, To the Honorable
